version = "0.1.13"
description = "WonderTranslate: automatic chat translation with native Aliucord update support"

aliucord {
    // These are explicit because WonderTranslate publishes verified GitHub Releases,
    // not the default 'builds' branch generated by the Gradle Aliucord extension.
    updateUrl.set("https://raw.githubusercontent.com/wonderkast02/WonderTranslate/refs/heads/main/updater.json")
    buildUrl.set("https://github.com/wonderkast02/WonderTranslate/releases/download/v0.1.13/WonderTranslate.zip")
    github("https://github.com/wonderkast02/WonderTranslate")
    changelog.set("R29: native Aliucord updater metadata; translation and UI unchanged from R28")
    deploy.set(false)
}
